import { expect, test, uniqueName } from "../../fixtures";

const W9 = "Legal Name: Acme Freight LLC\nTax ID: 12-3456789\nBusiness Type: LLC\n";
const CONTRACT = "Counterparty: Acme Freight LLC\nEffective Date: 2026-01-01\nExpiry Date: 2027-12-31\n";
const INSURANCE = "Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: 2027-03-31\n";

test("rejecting an extraction requires a note and returns the vendor to the member", { tag: "@REV-06" }, async ({ apiAs }) => {
  // Arrange: a vendor in review with three extractions
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");

  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Rev06 Vendor"), category: "logistics", contact_email: "ops@acme.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();

  for (const [kind, content, filename] of [
    ["w9", W9, "w9.txt"],
    ["insurance_certificate", INSURANCE, "insurance.txt"],
    ["contract", CONTRACT, "contract.txt"],
  ] as const) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: { kind, file: { name: filename, mimeType: "text/plain", buffer: Buffer.from(content) } },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submit.status(), await submit.text()).toBe(200);

  // Find the W-9 extraction once background processing has produced it.
  const documents = await (await member.get(`/api/vendors/${vendor.id}/documents`)).json();
  const w9Document = documents.find((d: { kind: string }) => d.kind === "w9");
  expect(w9Document).toBeTruthy();

  let w9Extraction: { id: string; status: string } | undefined;
  await expect
    .poll(async () => {
      const res = await member.get(`/api/documents/${w9Document.id}/extraction`);
      if (res.status() !== 200) return undefined;
      w9Extraction = await res.json();
      return w9Extraction?.status;
    })
    .toBe("pending_review");
  const extractionId = w9Extraction!.id;

  // Act 1: reject without a note
  const withoutNote = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: { decision: "reject" },
  });

  // Assert 1
  expect(withoutNote.status(), await withoutNote.text()).toBe(422);

  // Act 2: reject with a note
  const withNote = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: { decision: "reject", note: "Tax ID does not match" },
  });
  expect(withNote.status(), await withNote.text()).toBe(200);

  // Assert 2: vendor is rejected and the audit event is recorded
  await expect
    .poll(async () => {
      const res = await member.get(`/api/vendors/${vendor.id}`);
      return (await res.json()).status;
    })
    .toBe("rejected");

  await expect
    .poll(async () => {
      const res = await member.get(`/api/vendors/${vendor.id}/audit`);
      const trail = (await res.json()) as { items: { action: string }[] };
      return trail.items.map((event) => event.action);
    })
    .toContain("extraction.rejected");
});
